std::array<DrumPat,PATS> drums{};std::array<NotePat,PATS>bass{},melody{};std::array<std::array<int,BARS>,TRACKS>arr{};std::atomic_bool playing{false};std::atomic_int bpm{150},cur{-1},curBar{-1},master{50};std::thread ath;HWND win{};int page=3,editPat[3]={0,0,0};RECT playR{},minusR{},plusR{},volR{},newR{},openR{},saveR{},exportR{},tabs[4]{},patR[PATS]{},dp[D][STEPS]{},np[NOTES][STEPS]{},ap[TRACKS][BARS]{};
